import{_ as e,c as d,o,am as a}from"./chunks/framework.CiCI_NbS.js";const h=JSON.parse('{"title":"内部动作","description":"","frontmatter":{"prev":{"text":"宿主输入","link":"/docs/pogget/custom-vina/inputs"},"next":{"text":"绘制阶段与高级布局","link":"/docs/pogget/custom-vina/slots"}},"headers":[],"relativePath":"docs/pogget/custom-vina/actions.md","filePath":"docs/pogget/custom-vina/actions.md"}'),c={name:"docs/pogget/custom-vina/actions.md"};function n(r,t,i,s,p,g){return o(),d("div",null,t[0]||(t[0]=[a(`<h1 id="内部动作" tabindex="-1">内部动作 <a class="header-anchor" href="#内部动作" aria-label="Permalink to &quot;内部动作&quot;">​</a></h1><p><code>action</code> 是短按动作，<code>holdAction</code> 是长按动作，值必须是下表中的完整 ID。它们调用 Pogget 已有功能，不是可执行脚本。当前共注册 <strong>62 个动作</strong>，以下逐个说明。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MenuButton {</span></span>
<span class="line"><span>  view {</span></span>
<span class="line"><span>    type: &quot;button&quot;, interaction: &quot;title&quot;, z: 10,</span></span>
<span class="line"><span>    x: 180, y: 8, width: 100, height: 28,</span></span>
<span class="line"><span>    label: &quot;收纳盒菜单&quot;, textLiteral: true,</span></span>
<span class="line"><span>    action: pogget.action.container.menu</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>有效释放才会执行动作；移出、失焦、隐藏、禁用或按下期间热更新会取消手势。有 <code>holdAction</code> 的长按不会再执行短按动作。</p><h2 id="视图切换" tabindex="-1">视图切换 <a class="header-anchor" href="#视图切换" aria-label="Permalink to &quot;视图切换&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.view.toggle</code></td><td>在列表视图与图标视图之间切换，并保存设置</td></tr><tr><td><code>pogget.action.view.list</code></td><td>切换到列表视图，并保存设置</td></tr><tr><td><code>pogget.action.view.grid</code></td><td>切换到图标视图，并保存设置</td></tr><tr><td><code>pogget.action.listViewMenu</code></td><td>与 <code>view.list</code> 相同，切换到列表视图；不是打开子菜单</td></tr><tr><td><code>pogget.action.iconViewMenu</code></td><td>与 <code>view.grid</code> 相同，切换到图标视图；不是打开子菜单</td></tr></tbody></table><p>这五个动作在内联文件夹视图、自由网格排序或配置不可写时不执行切换。</p><h2 id="收纳盒与标题" tabindex="-1">收纳盒与标题 <a class="header-anchor" href="#收纳盒与标题" aria-label="Permalink to &quot;收纳盒与标题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.container.lock</code></td><td>切换布局锁定状态并保存；不切换位置锁定</td></tr><tr><td><code>pogget.action.container.personalization</code></td><td>打开当前收纳盒的个性化面板</td></tr><tr><td><code>pogget.action.container.collapse</code></td><td>折叠收纳盒；已折叠时不重复切换，包括悬停折叠后尚未展开的状态</td></tr><tr><td><code>pogget.action.container.expand</code></td><td>展开收纳盒；已展开时不重复切换</td></tr><tr><td><code>pogget.action.container.toggleCollapse</code></td><td>调用原生折叠/展开行为，遵循当前标题与悬停折叠状态</td></tr><tr><td><code>pogget.action.container.menu</code></td><td>调用标题“更多”按钮，打开收纳盒菜单</td></tr><tr><td><code>pogget.action.container.tagMenu</code></td><td>调用标题标签的原生点击行为，打开颜色标签相关菜单</td></tr><tr><td><code>pogget.action.container.searchMenu</code></td><td>调用搜索选项按钮，打开搜索选项菜单</td></tr><tr><td><code>pogget.action.container.hoverCollapse</code></td><td>调用折叠按钮的原生长按行为，进入悬停展开式折叠；已在该模式时保持；临时置顶会话中则结束该会话</td></tr><tr><td><code>pogget.action.container.pin</code></td><td>固定悬停展开后的收纳盒：退出悬停折叠并保持展开，保存该状态；不是窗口置顶开关</td></tr><tr><td><code>pogget.action.container.endTemporarySession</code></td><td>结束当前临时置顶会话，按原生规则恢复窗口状态</td></tr></tbody></table><p><code>collapse</code>、<code>expand</code>、<code>toggleCollapse</code> 要求配置可写。菜单、标签和固定等动作依赖当前原生控件存在。</p><h2 id="内联文件夹与编辑器" tabindex="-1">内联文件夹与编辑器 <a class="header-anchor" href="#内联文件夹与编辑器" aria-label="Permalink to &quot;内联文件夹与编辑器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.container.inlineBack</code></td><td>内联文件夹视图后退，交给原生导航处理；不在内联视图时无效</td></tr><tr><td><code>pogget.action.container.exitInlineSearch</code></td><td>退出内联文件夹搜索；要求处于搜索中，且不是内联编辑模式</td></tr><tr><td><code>pogget.action.container.inlineHome</code></td><td>清空内联文件夹导航历史并退出到收纳盒主页；编辑模式不执行</td></tr><tr><td><code>pogget.action.container.inlineSave</code></td><td>将当前内联编辑器内容保存为 UTF-8；要求正在编辑且存在文件路径</td></tr><tr><td><code>pogget.action.container.inlineOpen</code></td><td>用外部程序打开当前内联编辑文件；只在编辑模式且有文件路径时执行</td></tr><tr><td><code>pogget.action.container.toggleInlineSearch</code></td><td>开启或关闭内联文件夹/编辑器搜索，并更新输入焦点、搜索内容和滚动状态</td></tr></tbody></table><p><code>inlineHome</code>、<code>inlineSave</code>、<code>inlineOpen</code>、<code>toggleInlineSearch</code> 都要求内联视图存在、未进入待退出状态且目标文件夹可用。</p><h2 id="合并布局与窗口层级" tabindex="-1">合并布局与窗口层级 <a class="header-anchor" href="#合并布局与窗口层级" aria-label="Permalink to &quot;合并布局与窗口层级&quot;">​</a></h2><p>以下为原生菜单能力。每次调用都会按当前状态重建菜单并检查父项和子项；菜单中不存在或被禁用的动作不会执行，不会绕过原生限制。</p><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.mergedHostUseVerticalLayout</code></td><td>将合并收纳盒切换为纵向分隔布局；仅合并宿主提供</td></tr><tr><td><code>pogget.action.mergedHostUseTabLayout</code></td><td>将合并收纳盒切换为标签页布局；仅合并宿主提供</td></tr><tr><td><code>pogget.action.alwaysOnTopMenu</code></td><td>将窗口设为置顶层并保存，解除桌面嵌入</td></tr><tr><td><code>pogget.action.normalLayerMenu</code></td><td>将窗口设为普通层并保存，解除置顶和桌面嵌入</td></tr><tr><td><code>pogget.action.sendToBackMenu</code></td><td>将窗口设为底层并保存；根据全局桌面嵌入设置，嵌入桌面或置底</td></tr></tbody></table><h2 id="间距与分页" tabindex="-1">间距与分页 <a class="header-anchor" href="#间距与分页" aria-label="Permalink to &quot;间距与分页&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.spacingCompact</code></td><td>选择紧凑图标间距</td></tr><tr><td><code>pogget.action.spacingStandard</code></td><td>选择标准图标间距</td></tr><tr><td><code>pogget.action.spacingLoose</code></td><td>选择宽松图标间距</td></tr><tr><td><code>pogget.action.spacingPaged</code></td><td>启用分页布局，并打开分页布局设置窗口</td></tr><tr><td><code>pogget.action.spacingFixed</code></td><td>将间距类型设为固定；分页模式同时保存固定布局参数</td></tr><tr><td><code>pogget.action.spacingDynamic</code></td><td>将间距类型设为动态；分页模式同时保存动态布局参数</td></tr><tr><td><code>pogget.action.iconSpacingMenu</code></td><td>打开图标间距子菜单</td></tr></tbody></table><h2 id="排序" tabindex="-1">排序 <a class="header-anchor" href="#排序" aria-label="Permalink to &quot;排序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.sortFree</code></td><td>切换为自由排序，保留手动排列方式</td></tr><tr><td><code>pogget.action.sortNameAsc</code></td><td>按名称正序排序</td></tr><tr><td><code>pogget.action.sortNameDesc</code></td><td>按名称倒序排序</td></tr><tr><td><code>pogget.action.sortTimeAsc</code></td><td>按时间正序排序，较旧项在前</td></tr><tr><td><code>pogget.action.sortTimeDesc</code></td><td>按时间倒序排序，较新项在前</td></tr><tr><td><code>pogget.action.sortExtAsc</code></td><td>按扩展名正序排序</td></tr><tr><td><code>pogget.action.sortExtDesc</code></td><td>按扩展名倒序排序</td></tr><tr><td><code>pogget.action.sortSizeAsc</code></td><td>按文件大小正序排序，较小项在前</td></tr><tr><td><code>pogget.action.sortSizeDesc</code></td><td>按文件大小倒序排序，较大项在前</td></tr><tr><td><code>pogget.action.sortFreeGrid</code></td><td>启用自由网格排序；受实验室功能权限限制，未启用时进入相应功能入口</td></tr><tr><td><code>pogget.action.sortMenu</code></td><td>打开排序子菜单</td></tr></tbody></table><p>统一合并宿主的排序受原生策略限制。剪贴板收纳盒仅提供时间排序；自由网格还要求当前收纳盒支持该模式。</p><h2 id="锁定与设置菜单" tabindex="-1">锁定与设置菜单 <a class="header-anchor" href="#锁定与设置菜单" aria-label="Permalink to &quot;锁定与设置菜单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.unlockLayoutMenu</code></td><td>解除布局和位置锁定；当前存在任意锁定时提供</td></tr><tr><td><code>pogget.action.lockLayoutAndPosition</code></td><td>同时锁定布局与位置；在可用的锁定子菜单中提供</td></tr><tr><td><code>pogget.action.lockLayoutOnly</code></td><td>只锁定布局，位置保持未锁定</td></tr><tr><td><code>pogget.action.lockPositionOnly</code></td><td>只锁定位置，布局保持未锁定</td></tr><tr><td><code>pogget.action.lockLayoutMenu</code></td><td>打开锁定子菜单；当前未锁定时提供</td></tr><tr><td><code>pogget.action.personalizationMenu</code></td><td>打开当前收纳盒的个性化面板，与 <code>container.personalization</code> 对应同一功能</td></tr><tr><td><code>pogget.action.containerSettingsMenu</code></td><td>打开收纳盒设置子菜单</td></tr></tbody></table><p>合并宿主的锁定子菜单可能仅提供位置锁定。切勿把这些指定目标状态的动作解释成统一的“开关”。</p><h2 id="剪贴板与删除" tabindex="-1">剪贴板与删除 <a class="header-anchor" href="#剪贴板与删除" aria-label="Permalink to &quot;剪贴板与删除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内部动作</th><th>用途与条件</th></tr></thead><tbody><tr><td><code>pogget.action.pasteBoardCapacityTitle</code></td><td>打开剪贴容量设置窗口；仅剪贴板收纳盒提供</td></tr><tr><td><code>pogget.action.pasteBoardCategoryText</code></td><td>切换是否捕获文本；修改剪贴板捕获类别设置</td></tr><tr><td><code>pogget.action.pasteBoardCategoryImage</code></td><td>切换是否捕获图片</td></tr><tr><td><code>pogget.action.pasteBoardCategoryOtherFiles</code></td><td>切换是否捕获其他文件</td></tr><tr><td><code>pogget.action.pasteBoardFileCategories</code></td><td>打开剪贴板文件类别子菜单</td></tr><tr><td><code>pogget.action.pasteBoardClearAction</code></td><td>清空剪贴历史；成功后清空当前项目并刷新，保留剪贴板功能</td></tr><tr><td><code>pogget.action.pasteBoardClearAndCloseAction</code></td><td>清空剪贴历史，关闭剪贴板功能并移除该窗口</td></tr><tr><td><code>pogget.action.pasteBoardCloseOnlyAction</code></td><td>关闭剪贴板功能并移除窗口，保留已保存的剪贴历史</td></tr><tr><td><code>pogget.action.containerDeleteSubmenu</code></td><td>打开剪贴板收纳盒的清空/关闭子菜单</td></tr><tr><td><code>pogget.action.containerDeleteMenu</code></td><td>对普通收纳盒发起原生删除流程，具体确认与处理遵循该流程</td></tr></tbody></table><p>剪贴板相关菜单动作仅在剪贴板收纳盒提供。动作 ID 中保留 <code>Menu</code>、<code>Title</code> 等历史命名；实际用途以上表为准。</p><p>本页根据 <code>PersonalizationActions.hpp</code>、<code>PersonalizationMenuActions.inl</code> 的完整注册表，以及 <code>PoggetDesktopContainer.hpp</code> 的分派和菜单声明核对（2026-11-08）。其他模块即使使用相似的 <code>pogget.action.*</code> 名称，也不能作为 CustomVina 动作调用。</p>`,28)]))}const u=e(c,[["render",n]]);export{h as __pageData,u as default};
